<script setup lang="ts">import{ref}from'vue';import{ElMessage}from'element-plus';import{request}from'../../api/client';const form=ref({title:'',description:'',cover:'',country:'US',language:'en',total_episodes:1,is_paid:false,price_cents:499,currency:'USD'});async function create(){if(!form.value.title.trim()){ElMessage.warning('请输入标题');return}try{await request('/api/v1/admin/dramas',{method:'POST',headers:{'Content-Type':'application/json'},body:JSON.stringify(form.value)});ElMessage.success('创建成功');location.hash='#/dramas'}catch(e:any){ElMessage.error(e.message)}}</script>
<template><section><div class="title"><p>CONTENT / CREATE</p><h1>发布短剧</h1><span>创建后进入短剧管理发布</span></div><el-card><el-form label-width="110px" class="form"><el-form-item label="标题"><el-input v-model="form.title" placeholder="The Contract Wife"/></el-form-item><el-form-item label="简介"><el-input v-model="form.description" type="textarea"/></el-form-item><el-form-item label="封面 URL"><el-input v-model="form.cover"/></el-form-item><el-form-item label="国家"><el-input v-model="form.country"/></el-form-item><el-form-item label="语言"><el-input v-model="form.language"/></el-form-item><el-form-item label="总集数"><el-input-number v-model="form.total_episodes" :min="1"/></el-form-item><el-form-item label="付费"><el-switch v-model="form.is_paid"/></el-form-item><el-form-item v-if="form.is_paid" label="价格"><el-input-number v-model="form.price_cents" :min="1"/></el-form-item><el-form-item v-if="form.is_paid" label="币种"><el-input v-model="form.currency"/></el-form-item><el-button type="primary" size="large" @click="create">创建短剧</el-button></el-form></el-card></section></template>